import{c as n,Q as a,j as r,m as t}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Tangram: Unlocking Non-Uniform KV Cache Compression for Efficient Multi-turn LLM Serving","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.06302","title":"Tangram: Unlocking Non-Uniform KV Cache Compression for Efficient Multi-turn LLM Serving","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.06302,"authors":["Hyungmin Kim","Minsoo Kim","Hongseok Kim","Jungwook Choi"],"domains":["cs.LG"],"html":"https://arxiv.org/html/2606.06302v1","pdf_path":"pdfs/2606.06302.pdf","published_date":"2026-06-04T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-04-tangram-non-uniform-kv-cache-compression-2606-06302.md","filePath":"research/papers/2026-06-04-tangram-non-uniform-kv-cache-compression-2606-06302.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-06-04-tangram-non-uniform-kv-cache-compression-2606-06302.md"};function i(s,e,l,c,g,d){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="tangram-unlocking-non-uniform-kv-cache-compression-for-efficient-multi-turn-llm-serving" tabindex="-1">Tangram: Unlocking Non-Uniform KV Cache Compression for Efficient Multi-turn LLM Serving <a class="header-anchor" href="#tangram-unlocking-non-uniform-kv-cache-compression-for-efficient-multi-turn-llm-serving" aria-label="Permalink to &quot;Tangram: Unlocking Non-Uniform KV Cache Compression for Efficient Multi-turn LLM Serving&quot;">​</a></h1><p><strong>Authors</strong>: Hyungmin Kim, Minsoo Kim, Hongseok Kim, Jungwook Choi <strong>Published</strong>: June 04, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.06302" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.06302</a> · <a href="https://arxiv.org/html/2606.06302v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.06302 <strong>Categories</strong>: cs.LG <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.06302" target="_blank" rel="noreferrer">research/papers/pdfs/2606.06302.pdf</a> (15 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Multi-turn LLM serving accumulates dialogue history whose Key-Value (KV) cache grows with every turn and every user, quickly exceeding the model weights themselves and making memory -- not compute -- the binding constraint on throughput. Non-uniform KV compression, which allocates heterogeneous budgets across attention heads, preserves accuracy far better than uniform schemes, yet remains impractical: modern serving stacks assume identical KV lengths across heads, so heterogeneity traps freed memory as page fragmentation, spends up to 25% of prefill time reclaiming scattered pages, and skews GPU workloads that inflate decode latency by up to 1.7× or burn 15--20% of each decode step on re-planning. We observe that this heterogeneity need not be discovered at runtime: head-wise retention follows a two-level structural regularity -- an input-invariant head ranking with narrowly bounded per-head ratios -- that can be calibrated offline from as few as 50 samples. Building on this insight, we present Tangram, a serving framework that statically resolves what prior systems handle dynamically: Budget Reservation fixes each head&#39;s post-compression footprint at scheduling time, eliminating page reclamation; Ragged Paging clusters similar-budget heads into independent page tables, turning fragmentation into reclaimable memory; and Ahead-of-Time Load Balancing precomputes balanced GPU partitions with zero runtime planning. Implemented on vLLM, Tangram serves as a drop-in substrate for existing non-uniform compression methods, matching their accuracy while improving end-to-end throughput by up to 2.6× over the full-KV baseline.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li><strong>問題定義</strong>：Multi-turn LLM serving 中，KV cache 隨對話輪次累積，記憶體（而非算力）成為 throughput 瓶頸；non-uniform KV compression 雖精度更優，但現有 serving stack 無法有效支援異質 head budget。</li><li><strong>靜態化洞察</strong>：Head-wise retention 具備「兩層結構規律性」——head ranking 對輸入不變、per-head ratio 範圍窄——可從 50 個樣本 offline 校準，無需 runtime 動態計算。</li><li><strong>Budget Reservation</strong>：在 scheduling 階段靜態確定每個 head 壓縮後的記憶體佔用，消除 page reclamation 開銷。</li><li><strong>Ragged Paging</strong>：將相近 budget 的 head 歸入獨立 page table，將 fragmentation 轉為可回收記憶體。</li><li><strong>Ahead-of-Time Load Balancing</strong>：預計算 GPU partition 分配，decode 步驟零 re-planning 成本。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>相比 full-KV baseline，end-to-end throughput 提升最高 <strong>2.6×</strong>。</li><li>消除了 prefill 階段高達 <strong>25%</strong> 的 page reclamation 時間。</li><li>解決 decode latency 膨脹問題（舊方案可達 <strong>1.7×</strong> 延遲，每步燒 <strong>15–20%</strong> 在 re-planning）。</li><li>實作於 vLLM，可作為現有 non-uniform compression 方法的 drop-in substrate，精度不降。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文自述 offline 校準仰賴代表性 calibration data（50 samples），若 serving workload 分布偏移，靜態 budget 可能次優。</li><li>⚠️ Ragged Paging 與 Budget Reservation 的系統整合複雜度未深入討論；對非 vLLM serving stack 的移植成本不明。</li><li>評估聚焦 throughput 指標，未見對 tail latency（p99）的系統性報告。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>Context-management / token budget 類比</strong>：Tangram 的「靜態 budget reservation」與 <code>context-management.md</code> 中 NLAH 原則（Right context &gt; more context）及 token budget 管理在設計哲學上相通——兩者皆強調預先規劃資源分配，避免 runtime 動態重分配的不可預測性。</li><li><strong>判斷 vs 決定（跨切紀律）</strong>：論文的核心洞察是將 head ranking（判斷層，offline LLM 分析）與 page table 分配（決定層，確定性演算法）明確分離，對應 <code>core.md</code> 「LLM 只做判斷，確定性代碼做決定」原則的工程實踐案例。</li><li><strong>unverified_success 閘門</strong>：offline calibration 產出的靜態 budget 若未經 runtime 實測驗證即直接部署，構成典型 <code>unverified_success</code> 情境；Tangram 的設計隱含需要 workload distribution 穩定作為前提假設，⚠️ 實際部署前須驗證 calibration set 代表性。</li><li><strong>Multi-turn serving → multi-session memory 延伸</strong>：KV cache 跨 turn 累積的問題結構，與 workspace 中跨 session 記憶管理（<code>memory/MEMORY.md</code>、memory-compactor）在「歷史 context 如何有效壓縮保留」這一抽象層面具可類比性，⚠️ 但 LLM inference serving 與 agent session 管理屬不同工程域，直接套用須謹慎。</li></ul>',16)])])}const h=n(o,[["render",i]]);export{u as __pageData,h as default};
